{
  "name": "search_tickets",
  "description": "Search support tickets by query and status. Use when the user asks about a previously reported issue or a ticket’s status. Returns tickets with their titles, statuses, and last-updated dates. Full conversation history is included only when response_format is detailed.",
  "input_schema": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "description": "Search terms, such as a ticket title or customer email"
      },
      "status": {
        "type": "string",
        "enum": [
          "open",
          "pending",
          "closed"
        ],
        "description": "Filter by status; if omitted, search all statuses"
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 50,
        "default": 10,
        "description": "Maximum number of tickets returned per call"
      },
      "response_format": {
        "type": "string",
        "enum": [
          "concise",
          "detailed"
        ],
        "default": "concise",
        "description": "concise returns only id, title, and status; detailed includes conversation history"
      }
    },
    "required": [
      "query"
    ]
  }
}

